def transform(grid):
    # Find background (most frequent value)
    from collections import Counter
    counts = Counter(val for row in grid for val in row)
    bg = counts.most_common(1)[0][0]

    # Identify separator and markers
    sep_candidates = [v for v in counts if counts[v] > 1]
    # Separator is most common non-background
    non_bg = [v for v in counts if v != bg]
    if non_bg:
        sep_counts = Counter(non_bg)
        sep = sep_counts.most_common(1)[0][0]
    else:
        sep = bg

    # Find marker rows (rows with non-background values)
    marker_rows = []
    for r in range(len(grid)):
        has_marker = False
        for c in range(len(grid[0])):
            if grid[r][c] != bg:
                has_marker = True
                break
        if has_marker:
            marker_rows.append(r)

    # Find marker columns (columns with non-background values in marker rows)
    marker_cols = []
    for c in range(len(grid[0])):
        has_marker = False
        for r in marker_rows:
            if grid[r][c] != bg:
                has_marker = True
                break
        if has_marker:
            marker_cols.append(c)

    # Extract grid
    output = []
    for r in marker_rows:
        row_vals = []
        for c in marker_cols:
            val = grid[r][c]
            if val == sep:
                row_vals.append(bg)
            else:
                row_vals.append(val)
        output.append(row_vals)

    return output
